/** Unit prices in cents. */
export const PRICES = Object.freeze({
  'MUG-01': 1250,
  'TEE-02': 2400,
  'CAP-03': 1800,
  'PEN-04': 350,
})

/** Default stock levels. */
export const STOCK = Object.freeze({
  'MUG-01': 10,
  'TEE-02': 3,
  'CAP-03': 5,
  'PEN-04': 100,
})

export function unitPrice(sku) {
  const price = PRICES[sku]
  if (price === undefined) throw new Error(`unknown sku ${sku}`)
  return price
}
/** Discount codes: kind, value and the minimum subtotal (cents) the code needs. */
export const CODES = Object.freeze({
  SAVE10: { kind: 'percent', value: 10, minSubtotal: 10000 },
  FLAT5: { kind: 'fixed', value: 500, minSubtotal: 3000 },
})

/** Discount in cents for `subtotal` (cents) and an optional code; 0 when the code does not apply. */
export function discountFor(subtotal, code) {
  if (!code) return 0
  const rule = CODES[code]
  if (!rule) throw new Error(`unknown discount code ${code}`)
  if (subtotal > rule.minSubtotal) {
    if (rule.kind === 'percent') return Math.round(subtotal * rule.value / 100)
    return Math.min(rule.value, subtotal)
  }
  return 0
}
export class OutOfStockError extends Error {
  constructor(sku, wanted, available) {
    super(`${sku}: wanted ${wanted}, only ${available} in stock`)
    this.name = 'OutOfStockError'
    this.sku = sku
    this.wanted = wanted
    this.available = available
  }
}

/** Throw OutOfStockError when the order asks for more of a SKU than `stock` holds. */
export function checkStock(lines, stock) {
  for (const line of lines) {
    const available = stock[line.sku] ?? 0
    if (line.qty > available) throw new OutOfStockError(line.sku, line.qty, available)
  }
}
import { STOCK, unitPrice } from './catalog.js'
import { discountFor } from './discount.js'
import { checkStock } from './inventory.js'

export { OutOfStockError } from './inventory.js'

/**
 * Price an order. `lines` is a list of `{ sku, qty }`; the same SKU may appear
 * on several lines. Returns `{ subtotal, discount, total }` in cents.
 */
export function priceOrder(lines, { code, stock = STOCK } = {}) {
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) throw new Error(`bad quantity for ${line.sku}`)
  }
  checkStock(lines, stock)
  const subtotal = lines.reduce((sum, line) => sum + unitPrice(line.sku) * line.qty, 0)
  const discount = discountFor(subtotal, code)
  return { subtotal, discount, total: subtotal - discount }
}
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { discountFor } from '../src/discount.js'

test('no code, no discount', () => {
  assert.equal(discountFor(5000, undefined), 0)
})

test('SAVE10 takes 10% above the minimum', () => {
  assert.equal(discountFor(12000, 'SAVE10'), 1200)
})

test('SAVE10 applies at exactly 100.00', () => {
  assert.equal(discountFor(10000, 'SAVE10'), 1000)
})

test('FLAT5 applies at exactly 30.00', () => {
  assert.equal(discountFor(3000, 'FLAT5'), 500)
})

test('codes below the minimum give nothing', () => {
  assert.equal(discountFor(2999, 'FLAT5'), 0)
  assert.equal(discountFor(9999, 'SAVE10'), 0)
})

test('unknown codes are rejected', () => {
  assert.throws(() => discountFor(5000, 'NOPE'), /unknown discount code/)
})
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { priceOrder, OutOfStockError } from '../src/order.js'

test('prices a simple order', () => {
  assert.deepEqual(priceOrder([{ sku: 'MUG-01', qty: 2 }]), { subtotal: 2500, discount: 0, total: 2500 })
})

test('applies a discount code', () => {
  const result = priceOrder([{ sku: 'TEE-02', qty: 3 }, { sku: 'CAP-03', qty: 2 }], { code: 'SAVE10' })
  assert.deepEqual(result, { subtotal: 10800, discount: 1080, total: 9720 })
})

test('stock is checked per line', () => {
  assert.throws(() => priceOrder([{ sku: 'TEE-02', qty: 4 }]), OutOfStockError)
})

test('stock is checked across lines of the same SKU', () => {
  assert.throws(
    () => priceOrder([{ sku: 'TEE-02', qty: 2 }, { sku: 'MUG-01', qty: 1 }, { sku: 'TEE-02', qty: 2 }]),
    err => err instanceof OutOfStockError && err.sku === 'TEE-02' && err.wanted === 4 && err.available === 3,
  )
})

test('an order that uses exactly the stock passes', () => {
  const result = priceOrder([{ sku: 'TEE-02', qty: 1 }, { sku: 'TEE-02', qty: 2 }])
  assert.equal(result.subtotal, 7200)
})

test('rejects bad quantities', () => {
  assert.throws(() => priceOrder([{ sku: 'PEN-04', qty: 0 }]), /bad quantity/)
})
